True from collections import Counter, deque

def transform(grid):
    height, width = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    seen = set()
    output = [[background for _ in row] for row in grid]
    for r in range(height):
        for c in range(width):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            component = []
            queue = deque([(r, c)])
            seen.add((r, c))
            while queue:
                y, x = queue.popleft()
                component.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < height and 0 <= nx < width and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        queue.append((ny,nx))
            if len(component) < 4:
                continue
            min_r = min(y for y, x in component); max_r = max(y for y, x in component)
            min_c = min(x for y, x in component); max_c = max(x for y, x in component)
            box_area = (max_r-min_r+1) * (max_c-min_c+1)
            if max_r > min_r and max_c > min_c and len(component) / box_area >= 0.5:
                for y in range(min_r, max_r+1):
                    for x in range(min_c, max_c+1):
                        output[y][x] = color
    return output
